"""Intuition-first lessons. Every method gets a need, a concrete example, and defined notation."""

LESSONS = {}
def lesson(id, title, story, steps, terms, experiment, takeaway):
    LESSONS[id] = dict(title=title, story=story, steps=steps, terms=terms, experiment=experiment, takeaway=takeaway)

lesson('boolean', 'Keep the pages that obey your rule.', [
 'You have eight short documents and want pages mentioning both a battery and storage. You could read every page and put a tick beside it only when both words appear. That is the whole starting idea: keep or discard each page according to a rule.',
 'AND means “both conditions must hold”. OR means “at least one must hold”. NOT means “exclude pages that meet this condition”. This gives a group of matches, with no score saying one match is better. The technical name is Boolean retrieval.',
 'First decide which text the rule checks. In this guide, it checks the body shown in the result—not the title used to label that document. Lowercasing makes Battery and battery equal. It does not make batteries equal to battery.'
], [('Ask for both words', 'battery AND storage'), ('Check the actual body', 'D1 contains battery twice and storage twice.'), ('Keep or discard', 'D1 passes. A page with only batteries does not pass battery.')], [
 ('Query', 'The request you type, such as battery AND storage.'),
 ('Document and body', 'A document is one item being searched. Its body is the actual text searched in these labs; its title is only a label.'),
 ('Token', 'A piece produced by splitting text. Here, each run of letters or digits becomes a lowercase token.'),
 ('Exact match', 'The query token and stored token must be identical after the stated text processing.'),
 ('Normalization', 'A deliberate text transformation. Lowercasing is one kind. Reducing word forms to a common base is a separate, optional kind.'),
 ('Set and membership', 'A set is a group of items. Membership asks whether a document belongs in the group of matches.')
], 'Try battery, then batteries. Inspect the bodies before changing the rule. The separate two-sentence example lets you turn a very small, explicitly defined plural mapping on and off.',
 'Exact matching is exact against the text after its stated processing. It is never an unexplained promise that every spelling or word form will match.')

lesson('lexical', 'Let the more revealing words count more.', [
 'Suppose you ask for “solar battery storage”. One page repeats “battery” and another contains all three words. A yes/no filter can keep both, but you still need to decide which to read first.',
 'Give each matching word some credit. A word repeated on a page provides evidence about that page. A word found on almost every page is less helpful for distinguishing pages. Combining those two observations gives a simple weighted score.',
 'You can write each page as a row of numbers, one number per possible word. That row is called a vector. Comparing these rows lets us rank partial matches. “Lexical” simply means that the comparison is based on the words themselves.'
], [('Count within a page', 'battery occurs twice in D1.'), ('Check the collection', 'battery occurs in 3 of the 8 documents.'), ('Combine the evidence', 'Give its count a weight, then compare the weighted rows.')], [
 ('Term frequency · TF', 'How many times a token occurs in one document.'),
 ('Document frequency · df', 'How many documents contain a token at least once. Repeating it on one page does not increase df.'),
 ('Inverse document frequency · IDF', 'A weight that grows as a token becomes rarer across documents.'),
 ('Vector and dimension', 'A vector is a list of numbers. A dimension is one position in that list; here, a position stands for a particular word.'),
 ('Dot product', 'Multiply corresponding entries of two lists and add the products. Bigger entries can produce a bigger score.'),
 ('Cosine comparison', 'Compare the direction of two number lists after accounting for their lengths. Proportional lists point the same way.')
], 'Compare the same query with and without the length adjustment in the dropdown. Then try a word absent from every body. It should give no lexical matches.',
 'A high word-based score means strong evidence under this weighting rule. It does not prove the page answers the question.')

lesson('probabilistic', 'Repeated words should help—but not forever.', [
 'A page says “battery” once. A second mention may make you more confident it is about batteries. A hundred extra mentions should not make it a hundred times more useful. Also, one occurrence in a short note can be more revealing than one in an enormous report.',
 'BM25 is a scoring recipe built around those observations. Extra repetitions earn smaller and smaller increments. A separate setting controls how much document length changes the score. The letters and settings come after this idea; you can understand the tradeoff before reading the equation.',
 'There is another question you can ask: if this page were a little word generator, how likely would it be to produce your query words? A language model for retrieval assigns word probabilities to each page. This is a simple word-count model here, not a chatbot.'
], [('Notice a matching word', 'One battery mention gives some evidence.'), ('Limit repetition credit', 'The second mention adds less than the first.'), ('Account for page length', 'Compare a short focused note with a long broad report.')], [
 ('Score versus probability', 'A score orders items. A probability has a defined event and lies between 0 and 1. BM25 scores are not relevance probabilities.'),
 ('Saturation', 'Diminishing extra credit: another repetition still helps, but its additional benefit gets smaller.'),
 ('Length normalization', 'Adjust a count using document length so that long documents do not benefit simply from having more opportunities to mention words.'),
 ('k₁ and b', 'BM25 controls: k₁ sets repetition credit; b sets the strength of the length adjustment.'),
 ('Smoothing and μ', 'Mix a page’s word counts with the whole collection’s word counts so a missing page word need not get zero probability. μ controls how much background evidence is mixed in.'),
 ('Likelihood and logarithm', 'Likelihood asks how well observed query words fit a document model. A logarithm lets us add values instead of multiplying many tiny probabilities; it preserves their order for a fixed query.')
], 'Start with the repetition and length sliders. Set b to 0 to remove the length adjustment. Only then switch to the word-probability model and inspect one token’s calculation.',
 'The formula expresses assumptions about evidence. Different assumptions and settings can produce a different ordering on the same text.')

lesson('expansion', 'Ask the same question in words the pages use.', [
 'You ask for “power after sunset”. A useful page says “electricity at night”. A search that compares only identical words cannot connect the two, even though you can.',
 'One repair is to add electricity and night to the request. Another is to let you mark a useful page, then borrow words from it. You can also add likely questions to documents ahead of time, so later users have more ways to find them.',
 'All these approaches add or change search clues. They do not turn the added text into evidence that an answer is true. Adding the wrong clue can send the search toward a different topic.'
], [('Original request', 'power after sunset'), ('Add related search words', 'electricity + night'), ('Search the real collection', 'D2 becomes reachable through its actual body words.')], [
 ('Expansion', 'Add related words or another formulation to improve the chance of finding useful material.'),
 ('Relevance feedback', 'The user marks results as useful or unhelpful; the system uses those judgments to improve the next search.'),
 ('Pseudo-feedback', 'The system assumes early results are useful without a user checking them. That assumption can be wrong.'),
 ('Query drift', 'An added clue changes the intended topic, such as turning a search for the animal jaguar into a search for cars.'),
 ('Generated hypothesis', 'An invented answer-like paragraph used to guide search. It may contain errors and must be replaced by actual supporting sources.'),
 ('Weight', 'How much influence an original or added clue receives. A weight of 0 removes that clue’s contribution.')
], 'Try the original request, then controlled synonyms. The matching scores are calculated. The proposed rewrites are written teaching examples; this browser does not ask a language model to produce them.',
 'Better wording can recover missing evidence, but more wording is not always better. Preserve the original need and verify the new results.')

lesson('dense', 'Put similar meanings near each other.', [
 '“Store daytime power for later” and “use saved electricity at night” can describe the same need without sharing the most important words. Word-by-word comparison misses that connection.',
 'Imagine placing documents on a map. Put ones with similar meanings near each other, and put a new question near the documents it is likely to need. Real systems learn a map from examples. A location on that learned map is a list of numbers called an embedding.',
 'Our small map has just two deliberately named directions so you can see what moves. Real learned maps usually have many more directions, and an individual direction does not usually mean something as simple as “transport”.'
], [('Represent the request', 'Turn its meaning into a list of numbers.'), ('Use comparable document lists', 'Prepare each document’s numbers ahead of the search.'), ('Compare locations', 'Choose documents whose lists are close under the model’s comparison rule.')], [
 ('Embedding', 'A learned numerical description used to compare items. Similarity in that description is an approximation to usefulness.'),
 ('Dense vector', 'A number list with useful information spread across many entries, rather than a mostly empty dictionary of words.'),
 ('Encoder', 'A model that turns text or another input into a numerical description.'),
 ('Bi-encoder', 'A design that encodes the query and the document separately, allowing document descriptions to be prepared in advance.'),
 ('Cosine versus dot product', 'Cosine compares direction. Dot product also grows with vector length. Use the rule the model was trained for.'),
 ('Contrastive training', 'Learn by making useful query–document pairs score above unsuitable pairs.')
], 'Move the request’s direction. Then triple the car vector’s length: cosine scores should stay unchanged, while dot-product scores should change.',
 'Nearby meaning is a useful clue, not a guarantee of relevance. Exact codes, negation and multi-topic documents can still be difficult.')

lesson('sparse', 'Keep a small, weighted dictionary of clues.', [
 'Instead of putting a whole document at one location, imagine writing a vocabulary checklist beside it: battery, storage, grid, and many other possible words. Give useful clues a weight and leave most of the checklist empty.',
 'A model can learn both which clues matter and which related words to add. A request for “renewable storage” might add battery as a clue, even when the request never used that word.',
 'The word positions remain visible. “Sparse” means most weights are zero. The choice is not “neural or word-based”: a neural model can produce these word-based weights.'
], [('Start with the words', 'renewable + storage'), ('Learn a few extra clues', 'battery .72, solar .60, grid .36 in the default teaching example'), ('Multiply shared weights', 'Only clues present in both lists contribute to the score.')], [
 ('Sparse representation', 'A large list with mostly zero entries. Here, each entry names a vocabulary word.'),
 ('Impact or term weight', 'The amount of influence assigned to one word as a search clue.'),
 ('Learned expansion', 'A trained model activates a related vocabulary word even when that word was absent from the original input.'),
 ('SPLADE', 'A named family of models that learns sparse vocabulary weights and expansion for retrieval.'),
 ('Pruning', 'Drop weak clues to reduce work or storage. A dropped clue contributes nothing.'),
 ('Sparsity regularization', 'A training penalty that encourages the model to use fewer active clues.')
], 'Increase the expansion strength, then raise the pruning threshold. Watch whether battery disappears and whether its document loses its only matching clue.',
 'Keeping fewer clues makes the representation smaller, but the removed clue may be the one that would have found a useful document.')

lesson('late', 'Ask each important word to find its support.', [
 'A question has two important parts: solar and storage. A document that is excellent on solar but says little about storage should not look complete just because the solar match is strong.',
 'Keep a separate numerical description for each query word and each document word. For solar, find the best supporting document word. Repeat for storage. Add those best-support values.',
 'The document descriptions can be prepared ahead of time. Comparing them with this particular query happens later, during search. That is why this approach is called late interaction.'
], [('Separate the needs', 'solar | storage'), ('Find best support for each', 'solar: .90; storage: .80'), ('Add the best matches', '.90 + .80 = 1.70')], [
 ('Token vector', 'A list of numbers describing one token in its surrounding text. Real models can split a familiar word into smaller tokens.'),
 ('Interaction', 'A comparison between part of the query and part of a document.'),
 ('MaxSim', 'For each query token, take the largest document-token similarity, then sum those largest values.'),
 ('Similarity matrix', 'A table with query tokens as rows and document tokens as columns; each cell holds a pair’s similarity.'),
 ('ColBERT', 'A retrieval model family built around this token-level late comparison.'),
 ('Compression', 'Store numerical descriptions in less space, usually with some approximation error.')
], 'Compare a balanced document with one that mainly supports solar. Then select the repeated-evidence document: duplicating an identical column must not increase a row’s maximum.',
 'Each query token gets its own best support. The rule does not require a different document token for every query token.')

lesson('indexes', 'Find promising places without reading everything.', [
 'With eight documents, reading every one is easy. With millions, it becomes expensive. Before searching, organize the collection so the system can quickly find promising places to look.',
 'For words, keep a list of documents containing each word, like a book’s index. For numerical descriptions, group nearby items or build routes connecting neighbors.',
 'Some shortcuts still return the exact top results under a scoring rule. Other shortcuts may miss a nearby item in exchange for less work. This chapter is about that execution tradeoff, not about changing what “useful” means.'
], [('Organize once', 'Assign six points to three groups.'), ('Search selected groups', 'Visit the group whose center is nearest the question.'), ('Compare with a full search', 'Did that shortcut recover both true nearest neighbors?')], [
 ('Index', 'A prepared data structure that helps locate items quickly. It is distinct from the rule that scores them.'),
 ('Nearest neighbor', 'An item whose numerical description is close under the chosen distance or similarity.'),
 ('Exact search', 'Return the actual best items under the stated numerical rule, not a claim of perfect semantic relevance.'),
 ('Approximate nearest-neighbor search · ANN', 'A faster search that may miss some items the exact search would return.'),
 ('IVF and nprobe', 'IVF groups vectors around centers. nprobe is how many groups are searched for this query.'),
 ('Neighbor recall', 'The fraction of the exact top neighbors recovered by the shortcut. This differs from finding human-judged useful documents.')
], 'Search one group, then all three. At the default query position, one group recovers only one of the exact top two; all three recover both.',
 'A fast lookup can faithfully recover the wrong semantic neighbors. Model quality and search-approximation quality need separate checks.')

lesson('ranking', 'Read the shortlist more carefully.', [
 'Suppose a quick search finds a stack of possibly useful pages. Reading every page carefully would be expensive, but reading that small stack carefully is feasible. Use the quick stage to gather options, then spend more effort deciding their order.',
 'A candidate is an item in that stack. A rank is its position in the list. A reranker is a second scorer that receives the stack and reorders it. It cannot place a missing page at the top: that page has to enter the stack first.',
 'The lab makes this visible. D2 answers the intended solar-storage question in different words. A search requiring word overlap cannot find it by merely taking more matching results. A second, meaning-based source can supply it.'
], [('Gather a shortlist', 'Quick word matching proposes documents.'), ('Inspect each candidate', 'A more detailed scorer judges the request and page together.'), ('Reorder only those items', 'Missing candidates remain missing until another retrieval step adds them.')], [
 ('Candidate', 'One item passed to the next stage for consideration.'),
 ('Rank and score', 'Rank is a position: first, second, third. Score is the number used to choose that position; different scorers use different scales.'),
 ('Learning to rank', 'Learn an ordering rule from examples of useful and unhelpful results.'),
 ('Cross-encoder', 'A model that reads the query and candidate together, so it can compare their words in context.'),
 ('Pointwise, pairwise, listwise', 'Judge one item, compare a pair, or consider several items as a list.'),
 ('Large language model · LLM', 'A model trained to process and generate language. It can be adapted to judge documents, but its judgments still need validation.')
], 'Increase the word-only candidate budget to 8: D2 should remain absent because its word-match score is zero. Switch to the combined source and see when D2 can be reranked.',
 'Candidate coverage and final order are separate problems. A more capable second-stage scorer does not repair an empty spot in its input.')

lesson('fusion', 'Combine different searchers without confusing their scores.', [
 'Ask two librarians for useful pages. One looks for your exact words; the other looks for related meanings. Their lists overlap, but each may find a useful page the other misses.',
 'You need two decisions. First, which pages enter the combined pile? Then, how do you order them? One simple rule gives a page a vote for being near the top of either list, adding votes when both searchers find it.',
 'That is rank fusion. A different rule blends the actual scores, which requires care because “12” from one scorer need not be better than “0.8” from another. Finally, you may prefer complementary pages over five versions of the same evidence.'
], [('Two independent lists', 'Words: D1, D3… | Meaning: D2, D1…'), ('Combine the unique documents', 'A document found by either source can enter.'), ('Choose an ordering rule', 'Use positions, comparable scores, or a relevance-and-variety tradeoff.')], [
 ('Hybrid retrieval', 'A system that combines different retrieval signals, such as word matching and learned meaning.'),
 ('Fusion', 'The rule for combining several result lists or scores into one order.'),
 ('Reciprocal rank fusion · RRF', 'Give each document a contribution of 1/(k + its rank) per list; weighted versions multiply each contribution by a source weight.'),
 ('k versus depth', 'In RRF, k softens differences between rank positions. Depth says how many results are taken from a source. They are different controls.'),
 ('Normalization versus calibration', 'Normalization changes a score’s scale. Calibration tries to give scores an empirically justified meaning, such as an estimated probability.'),
 ('Diversity and MMR', 'Diversity means useful variety. Maximal marginal relevance (MMR) balances query relevance against repeating what is already selected.')
], 'First inspect the two lists. Move the word-source weight to either extreme. Then duplicate that source and notice that repetition gives it extra voting power, not independent evidence.',
 'Combining lists helps when they add useful, complementary evidence. More sources alone do not guarantee a better answer.')

lesson('structured', 'Follow connections and choose the right level of detail.', [
 'A note says Aurora makes Cell A. Another says Cell A uses sodium. Neither note alone answers “which material is used by the product Aurora makes?” Connecting the two does.',
 'Represent things as named points and facts as labeled connections. Following two connections is a two-hop lookup. A different question—“what themes connect all the projects?”—may need summaries of many connected records instead.',
 'You can also organize a long report as passages inside sections inside a whole-document summary. A broad question can start high in this hierarchy; a precise question can go straight to an original passage.'
], [('Find the named thing', 'Aurora'), ('Follow a supported connection', 'Aurora → makes → Cell A'), ('Follow the next one', 'Cell A → uses → sodium; both records are needed.')], [
 ('Entity and relationship', 'An entity is a named thing, such as a company. A relationship is a recorded connection, such as makes.'),
 ('Graph, node and edge', 'A graph is a collection of points and connections. A node is a point; an edge is one connection.'),
 ('Hop', 'One step along a connection. Two hops use two connections.'),
 ('Hierarchy', 'An organization with levels, such as report → section → passage.'),
 ('Community summary', 'An overview of a connected group of records. It should retain pointers to the supporting originals.'),
 ('GraphRAG and RAPTOR', 'Named systems using graphs or summary hierarchies to help find and organize evidence. They do more than the simple graph walk in this lab.')
], 'Follow one hop, then two. Remove the material connection and check that neither the lookup nor the summary pretends to know the material.',
 'A connection or summary only helps when its supporting records are present, reliable and relevant to the question.')

lesson('multimodal', 'Keep the kind of evidence the question needs.', [
 'A page contains a table and a chart. The question asks which option lasts longest. If you flatten the table into an unordered bag of words and numbers, 3000 may survive while the connection between 3000 and option B disappears.',
 'A careful text extractor can preserve table rows. A page-image representation can also retain positions, shapes and curves. The right choice depends on what the question needs—not on a rule that pictures are always better than text.',
 'The same principle applies to scientific objects: choose a representation that preserves the signal defining similarity. Comparing a molecular fingerprint is a different task from comparing sentences.'
], [('Start with a page', 'Options, numbers, rows and plotted curves.'), ('Choose what to preserve', 'Unordered tokens, structured rows, or image regions.'), ('Check answerability', 'Does the retained information still connect each value to its option?')], [
 ('Modality', 'A kind of signal, such as text, images, audio or a measured spectrum.'),
 ('Cross-modal retrieval', 'Use one kind of signal to find another, such as a written request to find an image.'),
 ('Page patch', 'A small image region whose numerical description can be compared with a query.'),
 ('Layout', 'How elements are arranged: row membership, columns, labels and relative positions.'),
 ('CLIP and ColPali', 'Named model families: CLIP aligns image and text descriptions; ColPali uses multiple descriptions of page-image regions.'),
 ('Fingerprint and Tanimoto', 'A fingerprint records selected features. For binary feature sets, Tanimoto is the number of shared features divided by the number present in either set.')
], 'Try the table question with all three representations. Then switch to the curve question: keeping only the table still loses the needed curve shapes.',
 'Preserving the clue makes an answer possible. It does not prove a model will interpret that clue correctly.')

lesson('frontier', 'Let the next search depend on what is still missing.', [
 'You are comparing two options. You have found a useful cost comparison, but nothing about durability. Repeating the same broad query may give you three more cost pages and still leave the comparison unfinished.',
 'A more deliberate search keeps a checklist: cost, durability and comparable conditions. After each result, mark what is supported and choose the next request to fill a gap. Stop when enough evidence is gathered or the search budget runs out.',
 'Recent systems explore many ways to do this: generating better queries, deciding when to search again, or learning to output document identifiers. Generating an identifier, finding evidence and writing an answer are three distinct operations.'
], [('List what the answer needs', 'Cost + durability + comparable conditions.'), ('Search one missing aspect', 'After finding cost, ask specifically about durability.'), ('Check support and stop', 'Count distinct supported aspects, not just the number of pages.')], [
 ('Generative model', 'A model that outputs text or other sequences. For retrieval it might output a query or document ID rather than an answer.'),
 ('RAG', 'Retrieval-augmented generation: retrieve external evidence, then give that evidence to a model that writes an answer.'),
 ('Agentic search', 'A process that chooses further searches or actions based on evidence already found.'),
 ('Aspect and coverage', 'An aspect is one part the answer needs. Coverage counts how many required parts have supporting evidence.'),
 ('Budget and stop rule', 'A limit on searches, time or cost, plus a condition for deciding that the process should stop.'),
 ('Reasoning-intensive retrieval', 'Finding relevant evidence may require understanding an unstated connection rather than merely matching topic words.')
], 'Allow three searches. Compare repeatedly looking for cost with deliberately searching for missing aspects. Three pages are not necessarily three kinds of evidence.',
 'A convincing plan or generated explanation is not itself source evidence. Verify what was found and preserve the links supporting each claim.')

lesson('evaluation', 'Check what was found—and what came first.', [
 'Imagine that five pages in your collection would help answer a question. Your search returns three of them and two useless pages. It found three of the five useful pages, and three of its five returned pages were useful. Those are two different questions.',
 'Order matters too. If the first useful page is buried below four useless ones, the search feels worse even if the same useful pages appear eventually. We need separate measurements for coverage, wasted reading and early useful results.',
 'The lab uses eight invented documents with stated grades. You can reorder them by hand and watch which measurements react. These grades belong to the one stated question; a document can be useful for a different question and still receive grade zero here.'
], [('Count useful pages found', '3 useful retrieved / 5 useful in the collection = 60% recall.'), ('Count useful pages returned', '3 useful retrieved / 5 returned = 60% precision.'), ('Inspect the order', 'First useful at rank 4 → reciprocal rank = 1/4 = .25.')], [
 ('Relevance judgment', 'A label saying whether, or how much, a document helps with a particular information need.'),
 ('Precision@k', 'Of the first k results, what fraction are relevant? Here, a grade above zero counts as relevant.'),
 ('Recall@k', 'Of all relevant documents in the collection, what fraction occur in the first k results?'),
 ('Reciprocal rank · RR', '1 divided by the position of the first relevant result. It is zero when none appears within the cutoff. MRR averages RR over several queries.'),
 ('nDCG', 'Compare the list’s rank-discounted relevance credit with the best possible credit for the same cutoff. Higher-grade early results earn more credit.'),
 ('Average precision · AP', 'At each relevant result, record the precision so far; add those values and divide by the total number of relevant documents. The lab states how its truncated prefix is handled.')
], 'Start with the ideal order, then move an irrelevant result to the top. Increase the cutoff k and check how precision, recall and early-result credit respond differently.',
 'One number cannot describe every user need. State the judged question, cutoff, candidate rules and computation budget before comparing systems.')

# Each row: plain title, problem, intuition/example, terminology explained before the formal account, equation notation.
METHODS = {
'boolean': [
 ('Require both words, either word, or an exclusion', 'A user sometimes wants a firm condition, not a guess about meaning.', 'Think of sorting cards into piles. For AND, keep cards in both piles. For OR, keep cards in either pile. NOT removes cards from a specified pile.', 'A postings list is the stored list of documents containing a token. Intersection means items shared by two groups; union means items in either group. Parentheses say which part to work out first.', 'A and B name sets of documents here, not word counts. ∩ means both groups; ∪ means either group.'),
 ('Keep words together, or close together', 'A page may contain energy and storage far apart without discussing the phrase energy storage.', 'Number the words in a sentence. To match an exact two-word phrase, the second word must be in the next numbered position. A nearby-word rule can allow a gap.', 'A positional index stores word locations as well as document IDs. Proximity is allowed distance. Phrase slop is a configured allowance for departures from exact adjacency.', 'position(word) is a token’s numbered location. +1 means immediately next. The example assumes two single tokens.'),
 ('Restrict the kind or date of a result', 'A relevant old page may still be unacceptable when the user needs a recent report.', 'First check “is it a report?” and “is its year at least 2020?” A document must satisfy both before it is eligible.', 'A field is one named part of a record. Metadata are descriptive fields such as year and type. A filter decides eligibility rather than supplying a relevance score. ANN is approximate numerical-neighbor search, explained in the indexes chapter.', 'd is one document. type(d) and year(d) are its metadata. ≥ means at least.'),
 ('Allow a stated spelling difference', 'A mistyped word should not always cause an empty result.', 'Turning batery into battery needs one inserted t. A spelling-repair rule that allows one edit can find that possibility; a meaning rule would be needed for a synonym.', 'Edit distance counts insertions, deletions or substitutions. Character n-grams are overlapping groups of n characters. OCR is text recognized from images, which can contain recognition mistakes.', 'edit_distance(a,b) is the smallest allowed edit count needed to change string a into string b.')
],
'lexical': [
 ('Reward repeated but distinctive words', 'A common filler word should not carry the same evidence as a rarer subject word.', 'Count battery within a page, then ask how many pages contain battery at all. Repetition helps; rarity helps distinguish this page from the others.', 'TF is the within-page count. IDF is the rarity-based weight. Smoothing adds small constants so unusual count cases remain defined. This lab uses one explicit TF–IDF convention.', 't is a token; d a document; w its weight. tf(t,d) counts occurrences; df(t) counts documents containing it; N is the number of documents. ln is the natural logarithm.'),
 ('Compare proportions instead of raw amounts', 'A long page can accumulate a large score simply because it contains more words.', 'Lists [1,1] and [2,2] have the same proportions: the second doubles both entries. Cosine treats their directions as identical even though one is longer.', 'The dot product multiplies corresponding entries and adds them. A vector’s norm is its numerical length. Dividing by both lengths removes pure scale.', 'q and d are weighted query and document vectors. q·d is their dot product. ||q||₂ and ||d||₂ are square-root-of-sum-of-squares lengths. A zero vector gets score 0 in this lab.'),
 ('Give a title or abstract extra influence', 'Mentioning a subject in a title may be a stronger clue than mentioning it in a footnote.', 'You could give title evidence twice the influence of body evidence. This is a deliberate preference, which should be checked against real judgments.', 'A field boost is a multiplier for evidence from one named field. BM25F is a particular multi-field model with its own length handling; an arbitrary boost is not automatically BM25F.', 'title_score and body_score are scores for separate fields. The multiplier 2 is illustrative. The shared text labs use body only, with no title boost.')
],
'probabilistic': [
 ('Order pages by estimated usefulness', 'Matching words are uncertain clues: a page may mention a topic yet fail to answer the question.', 'If one page is estimated to be more likely useful than another under the stated objective, show it earlier. The difficult part is estimating that likelihood well.', 'The Probability Ranking Principle describes an ideal ordering under its assumptions. The Binary Independence Model (BIM) is one estimator using word presence and simplifying independence assumptions. Log odds express probability evidence on an additive scale.', 'R=1 means relevant. P(R=1|q,d) means estimated relevance probability given query q and document d. The displayed expression is a ranking principle, not a fitted model in this browser.'),
 ('Limit the benefit of repeating a word', 'Repeating battery over and over should not overpower a concise page that addresses the full request.', 'At average page length, the example gives a repetition multiplier of 1 for one mention and 1.375 for two. The second mention helps, but does not double the credit.', 'BM25 combines rarity weights, diminishing repetition credit and a length correction. k₁ controls repetition credit; b controls length correction. log1p(x) means ln(1+x), keeping this lab’s IDF variant positive.', 'Σ adds over unique query tokens t. tf is the token count, |d| document length, avgdl mean length, IDF the defined rarity weight. k₁≥0 and 0≤b≤1. A missing term contributes 0, including at k₁=0.'),
 ('Handle short titles and long bodies separately', 'A title and body have different lengths and different jobs, so one length correction may not suit both.', 'Normalize each field’s count for its own typical length, choose its influence, then combine field evidence before applying the model’s repetition limit.', 'A stream or field is a distinct record part. BM25F extends BM25 to such fields with field-specific weights and normalization.', 'Σfield means add over fields. boost(field) is that field’s chosen multiplier; normalized_tf(field) is its length-adjusted token count. This is an explanatory outline, not a complete BM25F formula.'),
 ('Ask how readily a page would produce the query words', 'A document’s vocabulary can be used to judge how well the request fits its subject.', 'Pretend a page supplies words from a bag. Add some background words from the whole collection so a missing word does not always make the entire query impossible.', 'A document language model is a word-probability model here. Query likelihood evaluates the query under that model. Dirichlet smoothing adds background evidence controlled by μ; it is a later smoothing choice, not Ponte–Croft’s original estimator.', 'count(t,q) counts a query token; tf(t,d) its document count; |d| document length. P(t|C) is collection token count divided by all collection tokens. μ is background strength. log means natural log here; Σ adds over distinct t with their query counts.'),
 ('Measure how unusual the word evidence is', 'Raw counts alone do not tell you whether a pattern is surprising in this collection.', 'A word appearing unusually often in useful pages may be a better clue than one occurring at the same rate everywhere.', 'Divergence-from-randomness models compare observed counts with a background expectation. Relevance models estimate a word distribution for useful material, often using feedback. They are related statistical branches, not one shared algorithm.', 'The displayed arrow is a qualitative idea. There is no single numeric formula for all these families and no claim that this lab implements them.')
],
'expansion': [
 ('Connect alternate word forms and known synonyms', 'The words a person types may differ from those the writer chose.', 'A controlled list can connect car with automobile. Separately, a word-form mapping can connect batteries with battery. Spelling, word form and meaning are different reasons for a mismatch.', 'A thesaurus lists related meanings. Stemming applies rules to word endings; lemmatization aims at dictionary forms, often using grammatical analysis. Neither is enabled implicitly in the shared corpus.', 'The arrow proposes an expanded query; OR allows either listed token. It is a deliberate transformation, not strict identity between the original strings.'),
 ('Steer the request toward pages you marked useful', 'A user may recognize a useful result more easily than describe the perfect query.', 'On a map, move the query toward useful examples and away from unhelpful ones. The relative strengths control how far each group pulls.', 'A centroid is the average of a group’s numerical descriptions. Rocchio is the classic vector update using positive and negative relevance feedback.', 'q is the old vector; q′ the new vector. α preserves the original; β weights the relevant centroid; γ subtracts the nonrelevant centroid. mean is entry-by-entry averaging. The worked example uses no negative group, so its contribution is 0.'),
 ('Borrow clues from the early results', 'When user judgments are unavailable, initial results may offer useful vocabulary.', 'Search once, borrow some words from the first pages, then search again. A car-heavy first result for jaguar can lead the next search away from the animal.', 'Pseudo-relevance feedback assumes early results are relevant. RM3 is a particular relevance-language-model feedback approach; the lab’s simple top-document term borrowing is not RM3.', 'q and feedback_model are compatible word-weight distributions in this outline. λ is the mixture fraction, from 0 to 1. The browser’s demonstrator states its own simpler weighting rule.'),
 ('Give a document extra ways to be asked for', 'A useful page may never use the exact phrasing of a likely question.', 'Before users search, attach plausible questions the page answers. Those question words become extra routes to the original page.', 'doc2query names document expansion by query prediction. Offline means during preparation, before the live request. An index is the searchable stored structure.', 'The arrows describe preparation steps. Generated queries are added search text, not additional factual evidence in the original document.'),
 ('Rewrite a request or imagine an answer to search for', 'A short or conversational request can leave out the vocabulary needed to find the evidence.', 'Turn “power after sunset” into more explicit search language, or draft an answer-like paragraph and use its meaning to find real pages.', 'Multi-query search uses several formulations. HyDE means Hypothetical Document Embeddings: generate an answer-like document, encode it, then retrieve actual documents. The lab’s fixed lexical rewrite is deliberately only an analogy.', 'q is the original query. The arrows are stages, not a guarantee that a generated document is true. An encoder turns its text into numbers.')
],
'dense': [
 ('Discover broad word-usage patterns', 'Car and automobile never match literally, but their surrounding words may be similar.', 'If two groups of pages tend to discuss roads, engines and driving, compress those shared usage patterns into a smaller set of numerical clues.', 'Latent semantic indexing (LSI) uses singular value decomposition (SVD), a matrix-factorization method. A matrix is a rectangular table of numbers; a low-rank approximation keeps fewer underlying patterns.', 'X is the term-by-document table. Uₖ, Σₖ and Vₖ are its truncated factor matrices; k is the number of retained patterns, not a result cutoff. ≈ means approximate, and the superscript T transposes a matrix.'),
 ('Prepare each page’s description before the question arrives', 'Comparing a new question with every full page using a heavy model can be too slow.', 'Create a reusable number list for each page ahead of time. When a question arrives, create its list and compare lists rather than rereading the full collection jointly.', 'Bi-encoders have separate query and document encoding passes, sometimes using shared weights. SBERT and DPR are named examples with different training designs. First-stage retrieval gathers candidates for later steps.', 'Equery and Edoc are the chosen encoders. Their output vectors must share a compatible space. The dot is the trained similarity rule in this outline; not every embedding model uses an unnormalized dot product.'),
 ('Learn from useful examples and plausible mistakes', 'A model needs examples showing the difference between a relevant page and a merely related one.', 'For battery recycling, a manufacturing page is a more revealing wrong choice than a cooking recipe. Teach the model to prefer the useful pair over such plausible distractors.', 'Contrastive learning compares positive pairs with negative pairs. A hard negative is a plausible but unsuitable match. Temperature τ changes how sharply score differences affect the training loss.', 'L is a training penalty, not a search score. q is a query, d⁺ a positive document, dj the positive plus negative candidates, s their similarity, and τ a positive temperature. exp is the exponential; log is natural log.'),
 ('Tell the model what kind of similarity you need', '“About the same topic” can differ from “supports this claim” or “contradicts it”.', 'Include the goal with the request so the representation can reflect the task. Train across languages when users and documents may use different languages.', 'Instruction tuning uses task descriptions during training or encoding. Multilingual training uses multiple languages. A prefix is the exact extra text a particular model expects before the input.', 'E(instruction,query) means encode the query together with the required task instruction. It is a processing sketch, not one universal model interface.')
],
'sparse': [
 ('Learn which visible words are useful clues', 'A fixed count-based rule may overweight generic words and underweight a useful subject word.', 'A trained model can assign storage more influence than system in a storage article, while leaving the vocabulary positions visible.', 'An impact is a learned term contribution. Document expansion adds words; impact prediction weights them. Some designs combine these separate choices.', 'wquery(t) and wdoc(t) are query and document weights for word t. Σ adds their products over the vocabulary. A zero weight makes that term’s contribution zero.'),
 ('Add related vocabulary without hiding the word positions', 'Exact vocabulary overlap can miss a relevant page that uses another expression.', 'For renewable storage, activate battery as another clue. A page with a battery weight can now share evidence with the request.', 'SPLADE projects text onto a vocabulary-sized nonnegative vector. Its training encourages most weights to be zero, while retaining useful original and expanded terms.', 'wq(t) and wd(t) are weights of vocabulary term t. The sum runs over vocabulary entries, not just words literally appearing in the original query.'),
 ('Drop weak clues to save work', 'Keeping every possible expansion makes storage and lookup more expensive.', 'With weights .9, .6 and .2, a threshold of .5 retains the first two. The .2 clue may be weak overall yet still be the only route to a particular page.', 'Pruning removes entries. Quantization stores values with reduced precision. Regularization changes training to discourage an overly complex or dense representation.', 'keep(t) asks whether term t remains. w(t) is its current weight. ≥ includes equality: a term exactly at the threshold survives. The lab prunes query weights only.')
],
'late': [
 ('Collect the strongest support for every query part', 'One strong topic match should not completely hide a missing part of the question.', 'For solar, take the best cell in its row. For storage, take the best in that row. Add .9 and .8 to obtain 1.7.', 'ColBERT keeps contextual token vectors. MaxSim is the sum of row maxima in the query-token-by-document-token similarity table.', 'i indexes query tokens and j document tokens. qi·dj is a token-pair similarity; maxj selects the best document support for one query token. Σi adds once per query token.'),
 ('Keep detailed matches while storing fewer bytes', 'A token description for every document token can consume much more space than one description per page.', 'Store an approximate compact description plus a small correction, rather than storing every original number at full precision.', 'Residual compression represents the difference from a reference value compactly. Denoised supervision improves the training signals by reducing unreliable labels.', 'The arrows outline compression and approximate matching. No specific compression ratio or error is promised by this sketch.'),
 ('Search passages, then return their parent document', 'A long report may cover several topics that one numerical description blends together.', 'Search its sections separately. When two overlapping passages from the same report match, decide how to combine them and avoid presenting them as independent sources.', 'A chunk or passage is a smaller unit of text. Aggregation combines passage scores into a document score. Parent-document deduplication recognizes that several chunks came from the same original.', 'max passage_score selects the strongest passage as one possible document score. Other aggregation rules exist; this example does not assert that max is always best.')
],
'indexes': [
 ('Look up word locations and safely skip hopeless blocks', 'Most documents do not contain the query words, and many candidates cannot beat the current leaders.', 'Use a word-to-document list. If a whole block can score at most .4 while the last retained leader scores .7, that block cannot enter the winners under those valid bounds.', 'An inverted index maps terms to postings lists. WAND and block-max techniques use upper score bounds to skip work. Top-k means the k highest-scoring items under the chosen rule.', 'upper_bound(block) is a proven maximum possible score for that block. current kth score is the lowest score among the retained k leaders. Safe skipping depends on valid bounds and tie handling.'),
 ('Compare every item as a reference answer', 'You need a baseline showing which numerical neighbors a shortcut might miss.', 'Measure the distance to all six points and keep the nearest two. Then compare the shortcut’s output with those two.', 'A flat index stores vectors without a routing shortcut. An exhaustive scan evaluates every eligible vector. Batched GPU execution can make this practical for some sizes.', 'The work estimate counts vector entries touched: number of vectors times dimensions. It omits hardware and batching constants and does not claim measured latency.'),
 ('Navigate connected neighborhoods', 'Searching every numerical description can be too slow as the collection grows.', 'Imagine an express road network to reach a neighborhood, then local streets to inspect nearby houses. Sparse upper layers route the search; lower layers explore candidates more thoroughly.', 'HNSW means Hierarchical Navigable Small World. It is a layered neighbor graph. efSearch controls search breadth; it is not the number of dimensions or a model-quality setting.', 'The arrow describes a usual tradeoff, not a per-query theorem. More exploration costs more work and tends to improve agreement with exact neighbors.'),
 ('Search selected groups or compress the stored numbers', 'Very large collections need different speed and memory tradeoffs.', 'Group points around centers and search the nearest groups. Separately, replace detailed numeric pieces with short codebook IDs when memory is tight.', 'IVF is inverted-file vector partitioning; nlist is the group count and nprobe groups searched. PQ is product quantization using subvector codebooks. LSH is locality-sensitive hashing, a different routing family. Faiss is a library offering multiple index designs.', 'The displayed IVF rule means search nprobe of the nlist groups, then compare candidates inside them. The lab uses exact distances inside fixed groups; it does not simulate PQ or LSH.')
],
'ranking': [
 ('Learn from examples of the order people want', 'Hand-picked weights cannot always express the criteria that make one result more useful than another.', 'Training can judge each page individually, learn that A should beat B, or learn from a whole ordered group. These are different ways of supplying ordering feedback.', 'Pointwise, pairwise and listwise describe learning objectives. A loss measures training error. Clicks are imperfect labels because a high position itself attracts attention.', 'spositive and snegative are model scores for a useful and unsuitable item. The logistic pairwise loss shrinks as their score difference grows. It is not a relevance probability.'),
 ('Combine many clues with small decision rules', 'Words, date, authority and meaning may all matter, and their interactions can be complicated.', 'One small tree can ask whether a title matches; another can refine how much date matters for that kind of request. Add many such improvements while emphasizing important ordering errors.', 'Boosted trees add successive decision trees. LambdaMART fits ranking gradients, emphasizing swaps that would change the target ranking metric. A gradient is a direction for reducing the training error.', 'ΔNDCG is the change in normalized discounted cumulative gain from swapping two results. Its absolute value measures swap importance in this explanation; this is not the complete LambdaMART training equation.'),
 ('Read the question and page together', 'A page can share all the right topic words yet fail a qualification such as “does not require lithium”.', 'Show the model the request and one candidate together so it can inspect how their words relate, rather than relying only on two independently prepared summaries.', 'A cross-encoder jointly processes the pair. Cross-attention lets tokens use information from the other text. Truncation means cutting input to fit a model’s length limit.', 'model([query;document]) denotes one joint scoring pass. The output scale depends on the model; it is not automatically a calibrated probability.'),
 ('Ask a language model to compare the shortlist', 'Some relevance criteria are easier to describe in language than encode as a few fixed features.', 'Give the model candidate IDs with passages and ask which best satisfies the exact request. Check that every returned ID is real and appears only as allowed.', 'Pairwise ranking compares two candidates; listwise ranking orders a group. A permutation is a reordered list containing the same IDs. Order bias means presentation order changes the judgment.', 'The example input [A,B,C] and output [C,A,B] contain the same IDs once each. This is a valid permutation, not evidence that C is actually best.')
],
'fusion': [
 ('Choose which documents may enter the combined pile', 'Two searchers can agree on one page while each finds another unique useful page.', 'From [1,2] and [2,3], keeping anything either found gives [1,2,3]. Requiring agreement keeps only [2]. Passing one shortlist to another scorer is a different, sequential design.', 'Union includes either set; intersection requires both. A cascade applies stages one after another. Provenance records which source supplied a candidate.', 'Clexical and Cdense are candidate sets. ∪ means union. The expression chooses membership, not the final order.'),
 ('Give credit for appearing near the top', 'Two searchers may use incompatible score units, but both can say which item they put first.', 'With k=60, rank 1 earns 1/61 and rank 3 earns 1/63. A document found at both positions earns their sum, about .03227 in unweighted RRF.', 'RRF adds position-based contributions. Weighted RRF multiplies each source contribution by its weight. Missing candidates contribute zero, and ranks begin at 1.', 'ranklist(d) is document d’s 1-based position in one list. k≥0 is a smoothing constant. Σlists adds source contributions. The lab uses weights α and 1−α, so α=.5 gives half the unweighted sum.'),
 ('Blend scores only after stating their scales', 'Adding a large-valued word score to a small-valued meaning score can accidentally let one source dominate.', 'Rescale each list’s scores to a stated common range, then pick how much each source should influence the total. Inspect what happens when a list has just one item.', 'Min–max normalization maps a list’s minimum to 0 and maximum to 1. CombSUM adds comparable scores. CombMNZ additionally multiplies by how many systems contributed nonzero scores. None of these operations alone calibrates probability.', 'α is the lexical mixing fraction. 1−α is the semantic fraction. Normalized scores use the stated candidate set; the lab maps a constant list to all zeros and missing items to zero.'),
 ('Turn rank positions into votes, or learn a blend', 'There are several ways to prefer agreement across searchers, and each makes different assumptions.', 'In a length-3 list, give rank 1 three points, rank 2 two points and rank 3 one point. An item second in two lists gets four points under that rule.', 'Borda-style voting assigns rank-based points. Learned fusion fits a combination from judged examples. Missingness indicates that a source did not return an item, rather than pretending it gave a measured zero score.', 'list_length−rank+1 is this stated Borda convention, with ranks starting at 1. The convention is not universally shared by all Borda implementations.'),
 ('Prefer the next useful page that adds something new', 'Five near-duplicates may crowd out a page covering a missing part of the question.', 'Pick a useful first page. For the next, balance usefulness against similarity to what you already chose. Keep choosing using that updated comparison.', 'MMR means maximal marginal relevance. It is greedy: each selection depends on already chosen items. Jaccard similarity compares shared distinct tokens with tokens present in either document.', 'λ weights relevance; 1−λ weights redundancy. maxselected is the largest similarity to an already selected item. The empty selected set has redundancy 0 here. Scores must be put on compatible scales before subtraction.')
],
'structured': [
 ('Use links as one clue to importance', 'A page cited by many other pages may deserve attention, but importance alone does not say it answers this query.', 'Imagine credit flowing through links. Pages receiving credit from other important pages can accumulate authority; a separate query match still checks the requested topic.', 'PageRank is a query-independent link-importance measure. Outdegree is the number of outgoing links. Damping mixes link-following with occasional restarts; dangling pages need an explicit redistribution rule.', 'PR(v) is importance of page v. d is the link-following fraction here, not a document variable; N is page count. Σu→v sums over pages linking to v. The displayed basic equation omits explicit dangling-node redistribution.'),
 ('Join two facts that share a named thing', 'The answer can be split across records that do not individually mention the whole question.', 'Find the product made by the company, then use that product name to find its material. Both records are needed to support the conclusion.', 'Entity resolution decides whether two names refer to the same thing. A relational join combines records on a shared key. A hop follows one graph edge.', 'The arrows name relationships, not numerical operations. A path is valid evidence only if its constituent records support the stated connections.'),
 ('Search an overview, then drill into the original', 'A broad question may span sections that are hard to recognize from a single short passage.', 'Make summaries of groups of passages, then summaries of those summaries. A broad search can find a useful overview and follow its pointers down to evidence.', 'RAPTOR builds a recursively clustered and summarized text hierarchy. Recursive means repeat the same operation at another level. Abstractive summaries rewrite ideas instead of merely copying a passage.', 'The arrows describe levels from original chunks to higher summaries. They do not guarantee the summary preserves every fact.'),
 ('Summarize connected groups for corpus-wide questions', 'Some questions ask about themes across a collection, not the nearest paragraph about one fact.', 'Organize extracted things and relationships into connected communities. Summarize those groups, then use the relevant summaries to assemble a broader view.', 'GraphRAG combines an extracted entity graph with community reports and query-focused synthesis. A community is a group of more strongly connected nodes. This differs from the lab’s two-hop lookup.', 'The arrows describe the preparation and answering pipeline. Extracted connections and generated summaries remain claims to verify against original records.')
],
'multimodal': [
 ('Use a written request to find an image', 'An image may contain the requested object without its filename or caption using your words.', 'Learn comparable number lists from image–text pairs. A written request can then be compared with stored image descriptions.', 'CLIP uses contrastive training to align image and text representations. Normalized vectors have length 1, so their dot product equals cosine similarity.', 'normalized_text and normalized_image are compatible unit-length vectors. The dot product measures alignment in that model’s learned space; it does not prove the image answers an analytical question.'),
 ('Search a page while retaining its visual structure', 'The layout of tables, charts and labels can be part of the evidence a user needs.', 'Keep descriptions of multiple small page regions. Match query parts against those regions while retaining the page as the retrieval unit.', 'ColPali encodes rendered pages with vision-language models and uses late interaction. Rendering means producing a page image. Multiple patch vectors retain finer detail than one page summary vector.', 'The two-way arrow indicates comparisons between query tokens and page-region vectors. The schematic is not a neural-model calculation.'),
 ('Choose a similarity suited to the object', 'A sentence, spectrum and molecule preserve different kinds of information.', 'For binary feature sets {a,b,c} and {b,c,d}, two features are shared and four occur in either set. Shared-over-either gives 2/4=.5.', 'A binary fingerprint records whether selected features occur. Tanimoto for binary sets is the same shared-over-union ratio as Jaccard. Spectrum matching uses different signals and scoring choices.', 'A and B are feature sets. |A∩B| counts shared features; |A∪B| counts distinct features in either set. The example has a nonempty union; applications must define the empty-union case.')
],
'frontier': [
 ('Generate the name of a document to look up', 'Can a trained model learn to point directly to stored items, rather than produce a vector for a separate nearest-neighbor lookup?', 'The model outputs doc-42. A separate lookup loads that actual document and checks whether it exists and is allowed.', 'DSI means Differentiable Search Index. It learns query-to-document-ID generation. Constrained decoding restricts outputs to valid identifiers; it does not remove the need to resolve IDs against the corpus.', 'docID is a stored item’s identifier. The arrows are stages. Generating an ID is different from generating an answer or quoting source evidence.'),
 ('Find evidence before writing the answer', 'A language model’s remembered information may be incomplete, outdated or hard to cite.', 'Search the collection, gather relevant passages, then provide those passages with the question to the model that writes the response.', 'RAG is retrieval-augmented generation. The retriever selects evidence; the generator writes conditioned on that context. It can use many of the retrieval methods in this guide.', 'q is the question. retrieve(q) returns context. generate(q,context) produces an answer. Neither stage guarantees that the answer faithfully reflects the evidence.'),
 ('Decide whether another lookup is worth doing', 'Always retrieving a fixed number of passages can waste effort or add unrelated material.', 'Check whether the current answer needs external evidence, whether a found passage helps, and whether the response is supported before continuing.', 'Self-RAG is a particular trained system using reflection tokens—special output markers—for retrieval and critique decisions. A hand-written retry loop is not the same model.', 'The arrows describe a control policy. A critique is a model judgment that can itself be mistaken; it is not an independent factual oracle.'),
 ('Explain what evidence the question actually needs', 'The relevant document may discuss an underlying principle without sharing the question’s surface words.', 'For a coding error, identify the condition that caused it, then search for documentation about that condition rather than only copying the error wording.', 'Reasoning-aware query expansion makes intermediate interpretations explicit. DIVER combines several such stages with trained retrieval and reranking. Multi-stage means multiple distinct operations, not one larger similarity formula.', 'The arrows describe one class of pipelines. Every reasoning step can alter the information need, so its effect must be tested against actual relevant evidence.'),
 ('Use each search to fill an evidence gap', 'Repeated broad searches can return many pages about one aspect and leave another aspect unsupported.', 'After finding cost evidence, target durability. After both are found, check whether the measurements use comparable conditions.', 'An evidence portfolio is the set of sources supporting the required aspects. Agentic evaluation examines a sequence of search decisions as well as an isolated returned list. BRIGHT-Pro studies complementary evidence in this setting.', 'required_aspects and supported_aspects are sets. The minus sign means set difference: required parts that still lack support. Counting aspects does not establish the truth of their sources.')
]
}

TIMELINE_LESSONS = [
 ('Use word patterns to organize literature', 'Instead of relying only on manually assigned catalog labels, let patterns of words help machines describe and search written material.'),
 ('Keep documents that obey an exact rule', 'Ask for both words, either word, or an exclusion. The result is a group of matching documents; pure Boolean retrieval does not give them relevance scores.'),
 ('Experiment with showing better matches first', 'An exact rule can return many pages. Researchers explore giving word evidence weights and using feedback from useful results to improve their order.'),
 ('Let a useful result improve the next request', 'A user marks useful and unhelpful examples. Adjust the request toward the useful ones instead of forcing the user to invent perfect search words.'),
 ('Describe a page with a weighted number list', 'Give every vocabulary word a position and a weight. Pages become comparable number lists, allowing partial matches and geometric comparisons.'),
 ('Treat matching as uncertain evidence', 'A word match does not prove usefulness. The Probability Ranking Principle asks how results should be ordered if relevance probabilities can be estimated under the stated assumptions.'),
 ('Find hidden patterns connecting different words', 'Pages about similar subjects can share word-usage patterns even when their exact words differ. A smaller numerical description can retain some of those patterns.'),
 ('Compare search methods on shared questions', 'Use common documents, requests and relevance judgments so a gain is not simply the result of an easier private test collection.'),
 ('Stop repeated words from dominating the score', 'BM25 limits the extra credit for repeated terms and adjusts for document length, producing a durable word-based ranking recipe.'),
 ('Ask how likely a page is to produce the query words', 'Estimate a small word-probability model for each document and compare how well the query fits it. This is a retrieval language model, not a conversational chatbot.'),
 ('Use links for importance and variety for usefulness', 'Web links add an importance signal to text search. A separate line of work asks whether a result set repeats itself instead of covering different useful aspects.'),
 ('Learn the desired order from examples', 'Instead of choosing every weight by hand, use examples of useful results and ordering preferences to learn a scoring rule.'),
 ('Combine searchers using their list positions', 'Searchers may use incompatible numeric scales. Reciprocal rank fusion combines their 1st, 2nd and later positions through a stated voting rule.'),
 ('Make numerical lookup fast enough for large collections', 'A powerful meaning description is not enough if lookup takes too long. Neighbor graphs, compressed representations and GPU execution help reduce that cost.'),
 ('Read a query and page together—or prepare descriptions separately', 'Joint reading can improve judging a shortlist. Independently prepared descriptions make broad lookup practical. These choices suit different stages of a search system.'),
 ('Compare meaning, preserve word details and retrieve before writing', 'DPR, ColBERT and RAG develop different ideas: reusable passage descriptions, token-level comparisons and answering with retrieved evidence. They can be composed.'),
 ('Learn extra word clues and test across domains', 'SPLADE learns sparse vocabulary clues. BEIR tests whether retrieval quality transfers to new tasks. CLIP separately connects visual and textual descriptions.'),
 ('Store token-level descriptions more compactly', 'Keeping a description per token can cost substantial space. ColBERTv2 combines compression and improved training to make that detailed matching more practical.'),
 ('Generate an item ID—or an answer-like search clue', 'DSI learns to output document identifiers. HyDE uses an invented answer-like paragraph to locate real evidence. Generated identifiers and generated hypotheses need different checks.'),
 ('Use language models to judge lists and decide when to search', 'One approach asks a model to order candidate passages. Another trains decisions about whether to retrieve and whether an answer is supported. These are distinct components.'),
 ('Search connected records, summaries and visual pages', 'Different requests need different structures: connected facts, high-level summaries or page layout. GraphRAG, RAPTOR and ColPali explore those alternatives.'),
 ('Make descriptions and search plans reflect the task', 'Task instructions, stronger training data and reasoning about the request become important ways to improve retrieval. The cited work is representative, not a permanent leaderboard winner.'),
 ('Evaluate whether repeated searches gather missing evidence', 'A search process may find many related pages yet miss a required part of the answer. Recent evaluation examines complementary evidence and iterative search decisions.')
]

def attach(data):
    """Fail the build if any chapter or method lacks its intuition-first lesson."""
    for c in data['categories']:
        c['lesson'] = LESSONS[c['id']]
        rows = METHODS[c['id']]
        assert len(rows) == len(c['methods']), c['id']
        for m, (title, need, intuition, terms, notation) in zip(c['methods'], rows):
            m['lesson'] = dict(title=title, need=need, intuition=intuition, terms=terms, notation=notation)
    data['evaluation_lesson'] = LESSONS['evaluation']
    assert len(data['timeline']) == len(TIMELINE_LESSONS)
    for event, (title, story) in zip(data['timeline'], TIMELINE_LESSONS):
        event['lesson'] = dict(title=title, story=story)
    # Development periods overlap, but their starting dates should still read chronologically.
    data['timeline'].sort(key=lambda event: int(event['year'][:4]))
    data['teaching_reviewed'] = '21 October 2026'
    return data
